      u.parts.l.shin.rotation.x = 0.25 + 1.1 * a * Math.max(0, -Math.sin(ph - 0.6)); u.parts.r.shin.rotation.x = 0.25 + 1.1 * a * Math.max(0, Math.sin(ph - 0.6));
